// Typed access to src/mocks/examples.json (the contract's examples, generated by npm run gen:api).
import examples from './examples.json';

type Examples = Record<string, { method: string; path: string; examples: Record<string, Record<string, unknown>> }>;
const all = examples as Examples;

/** The example `name` (or the first one) for an operation's response `status` (or request body). */
export function example<T = unknown>(operationId: string, status: string, name?: string): T {
  const byName = all[operationId]?.examples[status];
  if (!byName) throw new Error(`No ${status} example for ${operationId} in contracts/openapi.yaml`);
  const value = name ? byName[name] : Object.values(byName)[0];
  if (value === undefined) throw new Error(`No example '${name}' for ${operationId} ${status}`);
  return structuredClone(value) as T;
}
